const _wh = $('Webhook Media').first().json || {};
const d = _wh.body || _wh;
const t = $('Tools Media').first().json || {};
const findings = [];

if (!t.ok) findings.push({level:'CRIT', text:'Jellyfin no responde'});
if (!t.seerr || !t.seerr.reachable) findings.push({level:'WARN', text:'HomeFlix/Seerr no responde'});
if (!t.threadfin || !t.threadfin.reachable) findings.push({level:'WARN', text:'Threadfin no responde'});
if (t.qbittorrent && t.qbittorrent.available && t.qbittorrent.active_torrents > 12) findings.push({level:'WARN', text:t.qbittorrent.active_torrents + ' torrents activos'});
for (const k of ['radarr','sonarr']) {
  const q = t[k] || {};
  if (q.available && (q.queued || 0) > 20) findings.push({level:'WARN', text:k + ' con ' + q.queued + ' elementos en cola'});
}
if (!findings.length) findings.push({level:'OK', text:'Stack multimedia sin incidencias'});

const severity = findings.some(f => f.level === 'CRIT') ? 'CRIT'
  : findings.length ? 'WARN' : 'OK';
const evidence = JSON.stringify({jellyfin:t.jellyfin, seerr:t.seerr, threadfin:t.threadfin, qbittorrent:t.qbittorrent, radarr:t.radarr, sonarr:t.sonarr}).slice(0, 4500);
const prompt = `Eres Agent-Media, empleado especializado de HomeLab Corp.
Tu jefe es HomeLab-Director. Analiza esta evidencia en tiempo real y entrega un
informe ejecutivo de 3 a 5 líneas en español, con hallazgos concretos y
recomendaciones de solo lectura. No reinicies nada, no borres nada, no expongas
secretos. Si no hay problemas, dilo explícitamente.

EVIDENCIA:
${evidence}

HALLAZGOS DETERMINISTAS:
${JSON.stringify(findings)}
`;
return [{json: {
  employee: 'Agent-Media',
  severity,
  quality_score: 0.9,
  findings,
  evidence,
  prompt,
  directive: d.directive || '',
  task_id: d.task_id || null,
  round_id: d.round_id || null,
  tool_data: t
}}];

const a = $('Analizar Media').first().json || {};
const l = $('LLM Media').first().json || {};
const choices = l.choices || [];
const text = ((choices[0] && choices[0].message && choices[0].message.content) || '').trim();
return [{json: {
  employee: a.employee,
  severity: a.severity,
  quality_score: a.quality_score,
  summary: (text || a.summary || 'Sin hallazgos').slice(0, 2500),
  findings: a.findings || [],
  evidence: a.evidence || '',
  directive: a.directive || '',
  task_id: a.task_id || null,
  round_id: a.round_id || null
}}];

const r = $('Rendir cuentas Media').first().json || {};
const d = $('Redactar informe Media').first().json || {};
return [{json: {...d, report_id: r.report_id || null, ledger_ok: !!r.ok}}];
